const priors=$("Build Tutor Request").all();
return $input.all().map((it,i)=>{
 const prior=priors[i]?.json||{},result=it.json||{};
 let text=String(result.output||result.text||"").trim();
 if(result.error||!text)text=String(prior.fallback||"I couldn’t answer just now. Try again—your task is safe.");
 text=text.replace(/https?:\/\/\S+/g,"").replace(/[ \t]+\n/g,"\n").trim();
 const limit=Math.min(120,Math.max(20,Number(prior.maxWords)||45));
 const words=text.split(/\s+/).filter(Boolean);
 if(words.length>limit)text=words.slice(0,limit).join(" ")+"…";
 const name=String(prior.material?.addressAs||"").replace(/[\r\n*_~`<>]/g," ").replace(/\s+/g," ").trim().slice(0,60);
 const nameWords=value=>' '+value.toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim()+' ';
 if(name&&!name.includes("@")&&!nameWords(text).includes(nameWords(name)))text=name+", "+text;
 return {json:{reply:text.slice(0,1500)},pairedItem:{item:i}};
});
